+		shearXMethod.setAccessible(true);
+
+		Graphics g = new BufferedImage(200, 100, BufferedImage.TYPE_INT_ARGB).getGraphics();
+		shearXMethod.invoke(captcha, g, 200, 100, Color.RED);
